#include "support/store_write_peer.h"
static void slCaps(xmqttversion Version)
{
    for(unsigned Mode=0;Mode<11;++Mode){
        jpdrive D={0};jpfile F=jpFile(&D);xmqttjournalconfig JC=stJournalConfig(Version);xmqttjournal* J=jpCreate(F,&JC);xmqttstorestateconfig SC=stConfig(Version);SC.WallMilliseconds=0;
        switch(Mode){case 0:SC.MaxOutgoing=0;break;case 1:SC.MaxIncoming=0;break;case 2:SC.MaxInbox=0;break;case 3:SC.MaxMemoryBytes=2048;break;case 4:SC.MaxTransactions=0;break;case 5:SC.MaxOperations=15;break;case 6:SC.MaxReplayBytes=31;break;case 7:SC.Delta.MaxOperations=0;break;case 8:SC.Delta.MaxBytes=31;break;case 9:if(Version==XMQTT_VERSION_5)SC.Delta.Codec.MaxProperties=0;else SC.Delta.Codec.MaxPayloadBytes=0;break;default:break;}
        xmqttstorestate* S=NULL;stStatus(xmqttStoreStateRecover(J,&SC,&S),XMQTT_STORE_DONE,"empty source under live resource caps");xtaskpool* Pool=jwPool(1);xmqttstorewriteconfig C;xmqttStoreWriteConfigInit(&C);if(Mode==10)C.MaxModelWork=0;xmqttstorewrite* W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,S,&C,&W),"bounded live model");xmqttstorewriteinfo Before=swInfo(W);unsigned Calls=D.Calls;stsource Source;stSource(Version,&Source);xmqttstoredeltaconfig DC=sdConfig(Version);xfuture* Future=swOps(W,&DC,Source.Ops,16);const xmqttcommitresult* R=jwOutcome(Future);xmqttstorewriteinfo After=swInfo(W);
        testRequire(R->Status==XMQTT_COMMIT_LIMIT&&!R->AppendCalled&&R->Effect==XMQTT_JOURNAL_NOT_COMMITTED&&D.Calls==Calls&&!After.Worker.Failed&&!After.State.Transactions&&!After.State.Operations&&!After.State.LastKey&&!After.State.ClientId.Size&&After.State.MemoryBytes==Before.State.MemoryBytes,"every model/decode/lifetime cap refuses before IO and refunds partial preparation");xrtFutureDestroy(Future);testRequire(xmqttStoreWriteDestroy(W),"cap owner retires");jwPoolDone(Pool);jpFileClose(F);
    }
}
static void slLate(xmqttversion Version,unsigned Stop)
{
    jwdrive D={0};jpfile F=jwFile(&D);xmqttjournalconfig JC=stJournalConfig(Version);xmqttjournal* J=jpCreate(F,&JC);xmqttstorestateconfig SC=stConfig(Version);SC.WallMilliseconds=0;xmqttstorestate* S=NULL;stStatus(xmqttStoreStateRecover(J,&SC,&S),XMQTT_STORE_DONE,"late outcome source");xtaskpool* Pool=jwPool(2);xmqttstorewriteconfig C;xmqttStoreWriteConfigInit(&C);xmqttstorewrite* W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,S,&C,&W),"late model owner");D.Base.Calls=0;D.Hold=4;sdsource Source;sdSource(Version,&Source);unsigned char Batch[SD_BUFFER];xmqttproperty Props[4];size_t N=0;sdStatus(xmqttStoreDeltaWrite(&SC.Delta,Source.Ops,2,Props,4,Batch,sizeof(Batch),&N),XMQTT_STORE_DELTA_DONE,"typed BIND/OPEN candidate");xfuture* Future=NULL;
    testRequire(xmqttStoreWriteAppendAsync(W,(xbytesview){Batch,N},Stop==1?1000:10000,&Future)==XMQTT_JWORK_ACCEPTED,"active typed candidate");jwAwait(&D.Entered);testRequire(!swInfo(W).State.Transactions,"prepared candidate invisible while real native sync blocked");
    if(Stop==0)testRequire(xrtFutureCancel(Future),"active transaction cancellation");else if(Stop==1)xrtSleep(1100);else testRequire(xmqttStoreWriteClose(W),"close during native append");
    testRequire(xrtFutureWaitFor(Future,1)==XWAIT_TIMEOUT,"local wait does not release active native duties");xrtAtomic32Store(&D.Release,1,XMEMORY_RELEASE);const xmqttcommitresult* R=jwOutcome(Future);xmqttstorewriteinfo Info=swInfo(W);
    testRequire(R->Status==(Stop==0?XMQTT_COMMIT_CANCELLED:Stop==1?XMQTT_COMMIT_TIMEOUT:XMQTT_COMMIT_CLOSED)&&R->Effect==XMQTT_JOURNAL_COMMITTED&&R->Sequence==1&&Info.State.Transactions==1&&Info.State.Operations==2&&Info.State.HasSession,"late local status cannot prevent committed model publication");testRequire(xmqttStoreWriteDestroy(W),"late native duties retired");jwPoolDone(Pool);jpFileClose(F);testRequire(jwOutcome(Future)==R&&R->Sequence==1,"late typed result remains independent");xrtFutureDestroy(Future);
}
typedef struct slwatch {xmqttstorewrite* W;xatomic32 Entered,Release,Released;} slwatch;
static void slNotice(ptr Data)
{slwatch* X=Data;testRequire(swInfo(X->W).State.Transactions==1&&xmqttStoreWriteWaitFor(X->W,0)==XWAIT_ERROR&&!xmqttStoreWriteDestroy(X->W),"model published before Watch; no same-pool/self destruction");xrtClearError();xrtAtomic32Store(&X->Entered,1,XMEMORY_RELEASE);jwAwait(&X->Release);}
static void slReleased(ptr Data){slwatch* X=Data;xrtAtomic32Store(&X->Released,1,XMEMORY_RELEASE);}
static void slWatch(void)
{
    jpdrive D={0};jpfile F=jpFile(&D);xmqttjournalconfig JC=stJournalConfig(XMQTT_VERSION_5);xmqttjournal* J=jpCreate(F,&JC);xmqttstorestateconfig SC=stConfig(XMQTT_VERSION_5);SC.WallMilliseconds=0;xmqttstorestate* S=NULL;stStatus(xmqttStoreStateRecover(J,&SC,&S),XMQTT_STORE_DONE,"watch source");xtaskpool* Pool=jwPool(1);jwblock Block={0};xfuture* Holding=xrtTaskSubmit(Pool,jwBlock,&Block,NULL);jwAwait(&Block.Started);xmqttstorewriteconfig C;xmqttStoreWriteConfigInit(&C);xmqttstorewrite* W=NULL;testRequire(xmqttStoreWriteCreate(Pool,J,S,&C,&W),"watch model owner");sdsource Source;sdSource(XMQTT_VERSION_5,&Source);xfuture* Future=swOps(W,&SC.Delta,Source.Ops,2);slwatch X={.W=W};xfuturewatch Watch;testRequire(xrtFutureWatchInit(&Watch,slNotice,slReleased,&X)&&xrtFutureWatchAdd(Future,&Watch)==XFUTURE_WATCH_PENDING,"queued real Watch");xrtAtomic32Store(&Block.Released,1,XMEMORY_RELEASE);jwAwait(&X.Entered);testRequire(xmqttStoreWriteClose(W)&&xmqttStoreWriteWaitFor(W,1)==XWAIT_TIMEOUT,"terminal Future cannot hide executing observer ownership");xrtAtomic32Store(&X.Release,1,XMEMORY_RELEASE);jwAwait(&X.Released);testRequire(xmqttStoreWriteWaitFor(W,10000)==XWAIT_OK&&xmqttStoreWriteDestroy(W),"watch/native tail physical join");jwPoolDone(Pool);jpFileClose(F);xrtFutureDestroy(Future);xrtFutureDestroy(Holding);
}
int main(void){for(unsigned I=0;I<2;++I){xmqttversion V=I?XMQTT_VERSION_5:XMQTT_VERSION_311;slCaps(V);for(unsigned S=0;S<3;++S)slLate(V,S);}slWatch();puts("[PASS]22 real quota refusals,six late COMMITTED model publications,invisible pending state and synchronous Watch physical retirement");return 0;}
